#!/usr/bin/env python3
"""Build self-contained, bilingual static pages. Python standard library only."""
from pathlib import Path
import json
from html import escape
from seo import metadata, write_discovery
ROOT=Path(__file__).resolve().parent.parent
SRC=ROOT/'_source'
CSS=(SRC/'style.css').read_text()
JS=(SRC/'app.js').read_text()
IMAGE_SOURCES = {(x['language'], x['name']): x for x in json.loads((SRC/'image-sources.json').read_text())}

def icon(name):
    shapes={
    'arrow':'<path d="M5 12h14m-6-6 6 6-6 6"/>',
    'up':'<path d="M6 18 18 6M6 6h12v12"/>',
    'check':'<path d="m5 12 4 4L19 6"/>',
    'lock':'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',
    'activity':'<path d="m3 13 4-1 3-8 4 16 3-8h4"/>',
    'sleep':'<path d="M20 14a8 8 0 0 1-10-10A8 8 0 1 0 20 14Z"/>',
    'heart':'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 1 9 8 15 7-6 12-11 8-15Z"/>',
    'body':'<circle cx="12" cy="4" r="2"/><path d="M5 9h14m-7-1v7m0 0-4 7m4-7 4 7"/>',
    'nutrition':'<path d="M20 3C8 2 2 7 6 15s15 2 14-12ZM4 21 16 8"/>',
    'mind':'<path d="M9 18H6v-5H3l3-4a7 7 0 1 1 13 5v7M10 9h6m-3-3v6"/>',
    'file':'<path d="M14 3H5v18h14V8l-5-5v5h5M8 12h8m-8 4h6"/>',
    'table':'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 10h18M9 4v16m6-10v10"/>',
    'code':'<path d="m7 7-5 5 5 5m10-10 5 5-5 5M14 3l-4 18"/>',
    'eye':'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
    'device':'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 5h4m-3 14h2"/>',
    'shield':'<path d="m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5l8-3Z"/><path d="m8 12 3 3 5-6"/>',
    'download':'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
    'zoom':'<path d="M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6"/>',
    'apple':'<path d="M15 3c0 2-1 3-3 3 0-2 1-3 3-3Z"/><path d="M17 12c0-2 1-3 2-4-2-2-4-2-7-1-3-1-7-1-8 4-1 4 3 10 5 10l3-1 3 1c2 0 4-4 5-6-2 0-3-2-3-3Z"/>',
    }
    return f'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">{shapes[name]}</svg>'

for lang in ('de','en'):
    def T(de,en): return de if lang=='de' else en
    home=T('index.html','index_en.html'); support=T('support.html','support_eng.html')
    store=T('https://apps.apple.com/de/app/strata-app/id6760822991','https://apps.apple.com/us/app/strata-app/id6760822991')
    price=T('9,99 €','$9.99')
    categories=[
      {'id':'activity','name':T('Aktivität','Activity'),'detail':T('Schritte, Distanz, Treppen, Energie und Training.','Steps, distance, flights climbed, energy and workouts.'),'metric':'steps','unit':'count'},
      {'id':'sleep','name':T('Schlaf','Sleep'),'detail':T('Schlafdauer und Schlafphasen aus Apple Health.','Sleep duration and sleep stages from Apple Health.'),'metric':'sleep_duration','unit':'hours'},
      {'id':'heart','name':T('Herz','Heart'),'detail':T('Herzfrequenz, Ruhepuls, HRV und Blutdruck.','Heart rate, resting heart rate, HRV and blood pressure.'),'metric':'resting_heart_rate','unit':'bpm'},
      {'id':'body','name':T('Körper','Body'),'detail':T('Gewicht, BMI, Körperfett und Körpertemperatur.','Weight, BMI, body fat and body temperature.'),'metric':'body_mass','unit':'kg'},
      {'id':'nutrition','name':T('Ernährung','Nutrition'),'detail':T('Wasser, Koffein, Energie und Makronährstoffe.','Water, caffeine, dietary energy and macronutrients.'),'metric':'water','unit':'ml'},
      {'id':'mind','name':T('Mental','Mind'),'detail':T('Achtsamkeit und weitere mentale Marker.','Mindful minutes and other mental wellbeing markers.'),'metric':'mindful_minutes','unit':'min'},
    ]
    screen_titles = [('01-datenschatz',T('Dein Datenschatz','Your data treasure')),('02-freigabe',T('Zugriff mit Klarheit','Access with clarity')),('03-aktivierung',T('Apple Health verbinden','Connect Apple Health')),('04-uebersicht',T('Dein Datenprofil','Your data profile')),('05-export',T('Deine Datenschichten','Your data layers')),('06-eigene-auswertung',T('Gezielt exportieren','Export what you need')),('07-einstellungen',T('Deine Einstellungen','Your settings'))]
    screens = []
    for name, title in screen_titles:
        asset = IMAGE_SOURCES[(lang, name)]
        screens.append({'file': Path(asset['output']).stem, 'title': title + (' (iPad)' if asset['device'] == 'iPad' else ''), 'width': asset['width'], 'height': asset['height']})
    config={'lang':lang,'categories':categories,'screens':screens,'sample':T('Beispieldaten','Sample data'),'headers':T(['Datum','Datentyp','Wert','Einheit'],['Date','Data type','Value','Unit']),'tableLabel':T('Exportvorschau mit fiktiven Beispieldaten','Export preview with fictional sample data'),'originalScreens':T('Aufbereitete App-Ansicht','Refined app view'),
    'formats':{'csv':{'title':T('Deine Daten. Bereit für Excel.','Your data. Ready for a spreadsheet.'),'desc':T('CSV für Tabellen, Vergleiche und eigene Diagramme.','CSV for spreadsheets, comparisons and your own charts.')},'json':{'title':T('Struktur für deine eigenen Tools.','Structure for your own tools.'),'desc':T('JSON für Skripte und die automatisierte Weiterverarbeitung.','JSON for scripts and automated processing.')},'markdown':{'title':T('Lesbar. Auch für deine lokale KI.','Readable. For you and your local AI.'),'desc':T('Markdown für Übersichten und lokale KI-Workflows.','Markdown for readable summaries and local AI workflows.')}},
    'newsletterConsent':T('Ich möchte per E-Mail Produkt-Updates zu Strata erhalten. Ich kann diese Einwilligung jederzeit per E-Mail an rm@kostenmanager.net widerrufen.','I would like to receive Strata product updates by email. I can withdraw this consent at any time by emailing rm@kostenmanager.net.'),
    'contactConsent':T('Ich habe die Datenschutzhinweise gelesen. Meine Angaben werden zur Bearbeitung meiner Anfrage übermittelt.','I have read the privacy information. My details will be transmitted to handle my request.'),
    'validation':T('Bitte ergänze eine gültige E-Mail-Adresse und deine Nachricht.','Please enter a valid email address and your message.'),
    'sending':T('Wird übermittelt …','Sending …'),'sent':T('Vielen Dank. Deine Angaben wurden übermittelt.','Thank you. Your details have been sent.'),'failed':T('Die Übermittlung hat nicht funktioniert. Deine Eingaben bleiben erhalten. Versuche es später erneut oder schreibe an rm@kostenmanager.net.','Your message could not be sent. Your entries have been kept. Please try again later or email rm@kostenmanager.net.')}
    def buy(placement,label=None,cls='btn btn-primary'):
        return f'<a class="{cls}" href="{store}" target="_blank" rel="noopener noreferrer" data-store="{placement}">{icon("apple")}{label or T("Im App Store kaufen","Buy on the App Store")}{icon("up")}</a>'
    def navigation(is_support=False):
        de='support.html' if is_support else 'index.html';en='support_eng.html' if is_support else 'index_en.html'
        links=''.join(f'<a href="{home if is_support else ""}#{anchor}">{label}</a>' for anchor,label in [('export',T('Export entdecken','Explore exports')),('how',T('So funktioniert’s','How it works')),('privacy',T('Deine Daten','Your data'))])
        return f'''<a class="skip" href="#main">{T('Zum Inhalt','Skip to content')}</a><header class="nav"><div class="wrap nav-inner"><a class="brand" href="{home}" aria-label="Strata {T('Startseite','home')}"><img src="assets/app-icon.webp" width="36" height="36" alt="">strata<span class="brand-dot">.</span></a><nav class="nav-links" aria-label="{T('Hauptnavigation','Main navigation')}">{links}</nav><div class="nav-end"><nav class="language" aria-label="{T('Sprache','Language')}"><a href="{de}" lang="de" hreflang="de" {'aria-current="page"' if lang=='de' else ''}>DE</a><span aria-hidden="true">/</span><a href="{en}" lang="en" hreflang="en" {'aria-current="page"' if lang=='en' else ''}>EN</a></nav>{buy('navigation',T('App kaufen','Get the app'),'btn btn-small')}</div></div></header>'''
    def footer():
        return f'''<footer class="footer"><div class="wrap"><div class="footer-top"><div class="footer-about"><a class="brand" href="{home}">strata<span class="brand-dot">.</span></a><p>{T('Deine Gesundheitsdaten. In deiner Hand.','Your health data. In your hands.')}</p></div><nav class="footer-links" aria-label="{T('Support und Rechtliches','Support and legal')}"><a href="{support}">Support</a><a href="{support}#contact" data-contact="support">{T('Kontakt','Contact')}</a><a href="{support}#contact" data-contact="updates">{T('Produkt-Updates','Product updates')}</a><a href="{support}#imprint">{T('Impressum','Legal notice')}</a><a href="{support}#website-privacy">{T('Datenschutz','Privacy')}</a><button type="button" data-privacy-settings>{T('Datenschutzeinstellungen','Privacy settings')}</button></nav></div><div class="footer-bottom"><span>© 2026 Robert Meyer · Strata App</span><span>{T('Entwickelt für iPhone & iPad. Gemacht für deine Daten.','Built for iPhone & iPad. Made for your data.')}</span></div></div></footer><aside class="sticky-buy" aria-label="{T('App kaufen','Get the app')}"><span><strong>Strata · {price}</strong><small>{T('Einmalkauf. Kein Abo.','Pay once. No subscription.')}</small></span>{buy('mobile',T('App kaufen','Get the app'),'btn btn-primary')}</aside>'''
    def extras():
        return f'''<aside class="cookie" id="privacy-notice" role="region" aria-label="{T('Datenschutzeinstellungen','Privacy settings')}" hidden><h2>{T('Du entscheidest. Auch hier.','Your choice. Here, too.')}</h2><p>{T('Diese Website setzt keine Cookies. Mit deiner Erlaubnis hilft uns Umami zu verstehen, welche Inhalte genutzt werden. Deine Auswahl speichern wir lokal im Browser.','This website uses no cookies. With your permission, Umami helps us understand which content is used. Your choice is saved locally in your browser.')} <a href="{support}#website-privacy">{T('Datenschutz','Privacy')}</a></p><div class="cookie-actions"><button type="button" data-consent="necessary">{T('Ohne Statistik weiter','Continue without analytics')}</button><button type="button" data-consent="analytics">{T('Statistik erlauben','Allow analytics')}</button></div></aside>
<dialog id="contact-dialog" aria-labelledby="contact-title"><div class="dialog-header"><h2 id="contact-title">{T('Direkt zu Robert.','Talk to Robert.')}</h2><button class="close-dialog" type="button" data-close aria-label="{T('Schließen','Close')}">×</button></div><p class="small muted">{T('Fragen zur App oder Interesse an Neuigkeiten? Hier erreichst du den Entwickler.','Questions about the app or interested in updates? Reach the developer here.')}</p><form class="form" id="contact-form"><label for="purpose">{T('Worum geht es?','What brings you here?')}</label><select id="purpose" name="purpose"><option value="support">{T('Frage / Support','Question / Support')}</option><option value="updates">{T('Produkt-Updates / Newsletter','Product updates / Newsletter')}</option></select><label for="contact-name">{T('Name (optional)','Name (optional)')}</label><input id="contact-name" name="name" autocomplete="name" maxlength="120"><label for="contact-email">{T('E-Mail-Adresse','Email address')}</label><input id="contact-email" type="email" name="email" autocomplete="email" required maxlength="254"><div id="message-field"><label for="contact-message">{T('Deine Nachricht','Your message')}</label><textarea id="contact-message" name="message" required maxlength="5000"></textarea><p class="small muted">{T('Bei technischen Fragen: App-Version und iOS/iPadOS-Version angeben. Bitte keine Gesundheitsdaten senden.','For technical questions, include your app and iOS/iPadOS versions. Please do not send health data.')}</p></div><div class="honey" aria-hidden="true"><label for="website">Website</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div><label class="check-label"><input type="checkbox" name="consent" required><span><span id="consent-copy">{config['contactConsent']}</span> <a href="{support}#website-privacy" target="_blank" rel="noopener">{T('Datenschutz lesen','Read privacy policy')}</a></span></label><button id="form-submit" class="btn" type="submit">{T('Absenden','Send')}{icon('arrow')}</button><p id="form-status" class="form-status" role="status" aria-live="polite"></p></form><p class="small muted">{T('Lieber per E-Mail?','Prefer email?')} <a href="mailto:rm@kostenmanager.net">rm@kostenmanager.net</a></p></dialog>
<dialog id="gallery-dialog" class="gallery-dialog" aria-labelledby="gallery-title"><div class="dialog-header"><h2 id="gallery-title">Strata App</h2><button class="close-dialog" data-close type="button" aria-label="{T('Schließen','Close')}">×</button></div><div class="gallery-content"><button class="gallery-nav" type="button" data-gallery-step="-1" aria-label="{T('Vorheriger Screenshot','Previous screenshot')}">←</button><img id="gallery-image" alt="" width="700" height="1521"><button class="gallery-nav" type="button" data-gallery-step="1" aria-label="{T('Nächster Screenshot','Next screenshot')}">→</button></div><p class="gallery-caption" id="gallery-caption" aria-live="polite"></p></dialog>'''
    def shell(content,title,desc,is_support=False):
        return f'''<!doctype html>
<html lang="{lang}"><head>{metadata(lang,title,desc,is_support)}<style>{CSS}</style></head><body>{navigation(is_support)}<noscript><div class="noscript">{T('Die interaktive Vorschau benötigt JavaScript. Alle App-Informationen und der Kauf-Link sind auch ohne JavaScript verfügbar. Kontakt:','The interactive preview needs JavaScript. App information and purchase links are available without it. Contact:')} <a href="mailto:rm@kostenmanager.net">rm@kostenmanager.net</a></div></noscript>{content}{footer()}{extras()}<script id="page-config" type="application/json">{json.dumps(config,ensure_ascii=False).replace('<','\\u003c')}</script><script>{JS}</script></body></html>'''

    layers=[]
    # A diagram of Strata's six data layers. No user records or product statistics are represented.
    for i,c in enumerate(categories):
        y=90+i*56
        wave=['M 225 1 l 15 -5 12 5 10 -21 12 26 12 -11 15 3 20 -7','M 225 1 q 12 -17 24 0 t 24 0 t 24 0 t 24 0','M 225 1 h 15 l 7 -6 7 10 9 -27 10 39 8 -16 h 26','M 225 1 l 18 -7 18 2 18 -11 18 4 18 -8','M 225 1 l 14 -8 14 4 14 -3 14 -9 14 3 14 -7','M 225 1 q 22 -15 44 0 t 44 0'][i]
        layers.append(f'''<g class="layer {'is-active' if i==0 else ''}" data-layer-index="{i}" style="--layer-color:var(--{c['id']})"><g transform="translate(0 {y})"><path class="layer-edge" d="M84 47 325 124 507 20v13L325 138 84 61Z"/><path class="layer-surface" d="m84 47 182-103 241 76-182 104Z"/><path d="m122 43 144-81 201 64" fill="none" stroke="currentColor" stroke-opacity=".07"/><g transform="translate(5 27) skewY(17)"><text class="layer-name" x="121" y="-5">{c['name']}</text></g><g transform="translate(8 -5) skewY(-12)"><path class="layer-line" d="{wave}"/></g><text class="layer-number" x="526" y="33">0{i+1}</text></g></g>''')
    visual=f'''<svg class="strata-visual" viewBox="0 0 590 575" aria-hidden="true"><defs><pattern id="grid" width="38" height="38" patternUnits="userSpaceOnUse"><path d="M38 0H0v38" fill="none" stroke="currentColor" stroke-opacity=".035"/></pattern></defs><rect width="590" height="575" fill="url(#grid)"/><path d="M84 82v378m241-321v378M507 25v403" stroke="currentColor" stroke-opacity=".12" stroke-dasharray="2 6"/>{''.join(reversed(layers))}<text x="82" y="529" fill="currentColor" opacity=".35" font-family="monospace" font-size="10">APPLE HEALTH → STRATA → CSV / JSON / MD</text></svg>'''
    pickers=''.join(f'<button class="layer-pick" type="button" data-layer-select="{i}" aria-pressed="{str(i==0).lower()}" style="--layer-color:var(--{c["id"]})">{c["name"]}</button>' for i,c in enumerate(categories))
    category_buttons=''.join(f'<button class="category-button" type="button" data-category="{i}" aria-pressed="{str(i==0).lower()}">{icon(c["id"])}{c["name"]}</button>' for i,c in enumerate(categories))
    outcomes=''.join(f'<article class="outcome">{icon(ic)}<div><h3>{h}</h3><p>{p}</p></div></article>' for ic,h,p in [
    ('table',T('Deine eigenen Vergleiche.','Your own comparisons.'),T('Daten in Excel oder Numbers öffnen und Verläufe selbst untersuchen.','Open your data in Excel or Numbers and explore changes over time.')),
    ('file',T('Deine eigene Übersicht.','Your own overview.'),T('Ausgewählte Daten als lesbare Datei für deine Unterlagen behalten.','Keep selected data in a readable file for your own records.')),
    ('code',T('Deine eigenen Werkzeuge.','Your own tools.'),T('Exporte mit Skripten oder einer lokalen KI weiterverarbeiten.','Process exports with scripts or an AI tool running locally.'))])
    workflow=''.join(f'''<article class="step"><div class="step-head"><span class="step-no">0{n+1}</span><h3>{h}</h3></div><p>{p}</p><button class="screen-btn" type="button" data-shot="{s}" aria-label="{T('Screenshot vergrößern: ','Enlarge screenshot: ')+screens[s]['title']}"><img src="assets/{lang}/{screens[s]['file']}.webp" alt="{screens[s]['title']}" width="{screens[s]['width']}" height="{screens[s]['height']}" loading="lazy" decoding="async"><span class="zoom">{icon('zoom')}</span></button></article>''' for n,(s,h,p) in enumerate([
    (1,T('Du gibst Zugriff.','You grant access.'),T('Erlaube Strata, ausgewählte Health-Daten zu lesen. Die Originaldaten werden nicht verändert.','Allow Strata to read selected Health data. Your original records stay unchanged.')),
    (3,T('Du siehst, was da ist.','See what’s there.'),T('Entdecke deine Datenbereiche, ihren Umfang und wie weit deine Historie zurückreicht.','Discover your data categories, how much they contain and how far back they go.')),
    (5,T('Du nimmst es mit.','Take it with you.'),T('Wähle einen Datenbereich und dein Format. Starte den Export direkt auf deinem Gerät.','Choose a data category and your format. Start the export right on your device.'))]))
    privacy_list=''.join(f'<li>{icon(ic)}<div><strong>{h}</strong><p>{p}</p></div></li>' for ic,h,p in [
    ('device',T('Lokal auf deinem Gerät.','Local to your device.'),T('Zugriff und Export funktionieren ohne Cloud-Pflicht.','Access and export work without a mandatory cloud service.')),
    ('eye',T('Lesen. Nichts verändern.','Read. Leave the originals.'),T('Strata liest deine Health-Daten und schreibt sie nicht um.','Strata reads your Health data without rewriting it.')),
    ('shield',T('Keine Registrierung. Kein Tracking.','No sign-up. No tracking.'),T('Die App hat keine Nutzerkonten, Werbung oder Nutzerprofile.','The app has no accounts, advertising or user profiles.')),
    ('download',T('Du entscheidest über jeden Export.','Every export is your decision.'),T('Eine Datei entsteht erst, wenn du es auslöst. Du wählst, ob und mit wem du sie teilst.','A file is only created when you request it. You decide if and with whom to share it.'))])
    faqs=[
    (T('Was bringt mir Strata zusätzlich zu Apple Health?','What does Strata add to Apple Health?'),T('Strata macht deinen vorhandenen Datenbestand als Datenschichten sichtbar und exportiert ihn als CSV, JSON oder Markdown. So kannst du die Daten in Tabellen, eigenen Skripten oder lokalen KI-Werkzeugen weiterverwenden.','Strata shows your existing records as data layers and exports them to CSV, JSON or Markdown. You can then use them in spreadsheets, your own scripts or local AI tools.')),
    (T('Brauche ich eine Apple Watch?','Do I need an Apple Watch?'),T('Entscheidend sind die bereits in Apple Health vorhandenen Daten und deine Lesefreigaben. Eine Apple Watch kann Daten beitragen; auch das iPhone und andere mit Health verbundene Apps können Daten liefern. Ohne Daten in einer Kategorie gibt es dort nichts zu exportieren.','What matters is the data already in Apple Health and the read access you grant. An Apple Watch can contribute data, as can your iPhone and other Health-connected apps. An empty category has nothing to export.')),
    (T('Verlassen meine Gesundheitsdaten mein Gerät?','Do my health data leave my device?'),T('Strata verarbeitet und exportiert lokal. Die App lädt deine Gesundheitsdaten nicht automatisch auf einen Server. Wenn du eine Exportdatei selbst teilst oder in ein externes Werkzeug hochlädst, gelten dessen Bedingungen.','Strata processes and exports on-device. The app does not automatically upload your health data to a server. If you choose to share an export or upload it to another tool, that tool’s terms apply.')),
    (T('Ist eine KI-Auswertung in der App enthalten?','Does the app include AI analysis?'),T('Strata stellt strukturierte Daten bereit. Die Auswertung findet in dem Werkzeug statt, das du selbst wählst, beispielsweise einer lokal laufenden KI. Strata liefert keine Diagnose, Therapieempfehlung oder medizinische Bewertung.','Strata provides structured data. Analysis happens in a tool you choose, such as an AI model running locally. Strata does not provide diagnoses, treatment recommendations or medical interpretations.')),
    (T('Welche Geräte und Sprachen werden unterstützt?','Which devices and languages are supported?'),T('Strata ist für iPhone ab iOS 17 und iPad ab iPadOS 17 erhältlich. Die App-Oberfläche unterstützt Deutsch und Englisch. Die verfügbaren Daten hängen von deinem Gerät, deinen Health-Daten und den erteilten Leserechten ab.','Strata is available for iPhone with iOS 17 or later and iPad with iPadOS 17 or later. The interface supports German and English. Available data depend on your device, Health records and read permissions.')),
    (T('Ist der Preis wirklich einmalig?','Is it really a one-time purchase?'),T('Ja. Strata wird als Einmalkauf ohne Abo angeboten. Der deutsche App Store zeigt aktuell 9,99 €. Es gilt der Preis, der dir beim Kauf in deinem App Store angezeigt wird.','Yes. Strata is a one-time purchase with no subscription. The US App Store currently lists $9.99. Your purchase is charged at the price displayed in your local App Store.')),
    (T('Warum heißt die App Strata?','Why is it called Strata?'),T('Strata bedeutet Schichten. Die App ordnet deinen Gesundheitsdatenbestand in sechs Datenschichten – von Aktivität bis mentaler Gesundheit.','Strata means layers. The app organises your health records into six data layers, from activity to mental wellbeing.')),
    ]
    faq_html=''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faqs)
    main=f'''<main id="main"><section class="hero"><div class="wrap"><div class="hero-grid"><div class="hero-copy reveal"><p class="eyebrow accent">{T('Apple Health. Weitergedacht.','Take Apple Health further.')}</p><h1>{T('Deine Health-Daten.<br><span>Bereit für mehr.</span>','Your health data.<br><span>Ready for more.</span>')}</h1><p class="hero-lead">{T('Hole deine Aktivitäts-, Schlaf- und Gesundheitsdaten aus Apple Health. Für Excel, eigene Auswertungen oder lokale KI. Direkt auf deinem iPhone oder iPad.','Take your activity, sleep and health data beyond Apple Health. Into spreadsheets, your own analysis or local AI. Right from your iPhone or iPad.')}</p><div class="hero-actions">{buy('hero',T('Für 9,99 € kaufen','Buy for $9.99'))}<a class="text-link" href="#export">{T('Export entdecken','Explore exports')}{icon('arrow')}</a></div><div class="micro-trust"><span>{icon('check')}{T('Einmalkauf · Kein Abo','Pay once · No subscription')}</span><span>{icon('lock')}{T('Lokal · Ohne Konto','On-device · No account')}</span></div></div><div class="hero-art reveal"><div class="art-meta"><span>{T('06 Schichten. Deine Geschichte.','06 layers. Your story.')}</span><span>{T('Auf deinem Gerät','On your device')}</span></div>{visual}<div class="layer-picker" role="group" aria-label="{T('Datenschicht entdecken','Explore a data layer')}">{pickers}</div><p class="layer-caption" id="layer-caption" aria-live="polite">{categories[0]['detail']}</p></div></div><div class="hero-bottom"><span>{T('Deine Daten können mehr als in Health liegen.','Your data can do more than stay in Health.')}</span><div class="formats"><span>CSV</span><span>JSON</span><span>MD</span>{T('Offen für deine Ideen.','Open to your ideas.')}</div></div></div></section>
<section class="section light" id="export"><div class="wrap"><p class="eyebrow">{T('01 / Aus Daten wird etwas Eigenes','01 / Make your data your own')}</p><div class="section-heading"><h2>{T('Nicht nur ansehen.<br>Etwas damit anfangen.','Don’t just see it.<br>Make something of it.')}</h2><p>{T('Wähle eine Kategorie und ein Format. Entdecke, wie du deine Daten weiterverwenden kannst.','Choose a category and format. See how you could put your data to use.')}</p></div><div class="demo-layout"><div class="demo-sidebar"><p>{T('Deine Datenbereiche','Your data categories')}</p><div class="category-list" role="group" aria-label="{T('Beispielkategorie','Sample category')}">{category_buttons}</div></div><div class="demo-main"><div class="demo-toolbar"><div class="format-controls" role="group" aria-label="{T('Exportformat','Export format')}"><button class="format-button" type="button" data-format="csv" aria-pressed="true">CSV</button><button class="format-button" type="button" data-format="json" aria-pressed="false">JSON</button><button class="format-button" type="button" data-format="markdown" aria-pressed="false">Markdown</button></div><span class="sample-label">{T('Beispieldaten','Sample data')}</span></div><div class="export-use" aria-live="polite"><div><h3 id="export-title">{config['formats']['csv']['title']}</h3><p id="export-desc">{config['formats']['csv']['desc']}</p></div><span class="file-label" id="file-label">strata-example-activity.csv</span></div><div class="export-output" id="export-output" tabindex="0" role="region" aria-label="{T('Beispielausgabe','Sample output')}"><pre>date,type,value,unit\n2026-03-01,steps,8240,count\n2026-03-02,steps,9106,count</pre></div><div class="demo-footer"><p>{T('Illustrative Vorschau mit fiktiven Daten. Die genaue Exportstruktur kann je nach Datentyp abweichen. Kein Zugriff auf deine Health-Daten im Browser.','Illustrative preview with fictional data. Actual export structure may vary by data type. This browser never accesses your Health data.')}</p><button class="download-link" type="button" id="download-sample">{icon('download')}{T('Beispiel herunterladen','Download sample')}</button></div></div></div><div class="outcomes">{outcomes}</div></div></section>
<section class="section how" id="how"><div class="wrap"><p class="eyebrow accent">{T('02 / So einfach ist der Weg','02 / A simple way forward')}</p><div class="section-heading"><h2>{T('Von Apple Health<br>in deine Hand.','From Apple Health<br>into your hands.')}</h2><p>{T('Drei Schritte. Du behältst die Kontrolle – vom ersten Zugriff bis zur fertigen Datei.','Three steps. You stay in control, from the first permission to the finished file.')}</p></div><div class="workflow">{workflow}</div><div class="screen-note"><span>{T('Aufbereitete App-Ansichten auf Basis der Original-Screenshots. Umfang und Historie richten sich nach deinen Health-Daten.','Refined app views based on the original screenshots. Coverage and history depend on your Health data.')}</span><button type="button" data-shot="0">{T('Alle 7 Ansichten ansehen','See all 7 screens')} ↗</button></div></div></section>
<section class="privacy-section" id="privacy"><div class="wrap privacy-grid"><div><p class="eyebrow accent">{T('03 / Privat bleibt privat','03 / Private stays private')}</p><h2>{T('Deine Gesundheit.<br>Deine Daten.<br><span class="accent">Deine Entscheidung.</span>','Your health.<br>Your data.<br><span class="accent">Your decision.</span>')}</h2><p class="privacy-lead">{T('Gesundheitsdaten sind persönlich. Deshalb findet die Arbeit dort statt, wo deine Daten sind: auf deinem Gerät.','Health data are personal. So the work happens where your data are: on your device.')}</p><div class="privacy-diagram"><span>Apple Health</span> → <span>Strata</span> → <span>{T('Deine Datei','Your file')}</span></div><a href="{support}#app-privacy" class="text-link">{T('Mehr zum App-Datenschutz','More about app privacy')}{icon('arrow')}</a></div><ul class="privacy-list">{privacy_list}</ul></div></section>
<section class="price-section" id="buy"><div class="wrap price-grid"><div><p class="eyebrow">{T('04 / Einmal kaufen. Weiterdenken.','04 / Buy once. Go further.')}</p><h2>{T('Dein nächster Schritt?<br>Deine Daten nutzen.','Your next step?<br>Put your data to use.')}</h2><p>{T('Alle sechs Datenschichten. Drei Exportformate. Und die Freiheit, selbst zu entscheiden, was du daraus machst.','All six data layers. Three export formats. And the freedom to decide what you make of them.')}</p></div><div class="price-details"><div class="price">{T('9,99<span>€</span>','$9.99')}</div><p class="price-sub">{T('Einmalkauf. Kein Abo. Kein Nutzerkonto.','One-time purchase. No subscription. No account.')}</p><div class="price-buy">{buy('pricing')}<a href="{store}" target="_blank" rel="noopener noreferrer" data-store="qr" aria-label="{T('QR-Code: Strata im App Store','QR code: Strata on the App Store')}"><img class="qr" src="assets/qr-{lang}.svg" width="80" height="80" alt="{T('Mit dem iPhone scannen, um Strata im App Store zu öffnen','Scan with your iPhone to open Strata on the App Store')}" loading="lazy"></a></div><p class="requirements">{T('Für iPhone ab iOS 17 und iPad ab iPadOS 17. Deutsch & Englisch. Es gilt der Preis in deinem App Store.','For iPhone with iOS 17+ and iPad with iPadOS 17+. German & English. Your local App Store price applies.')}</p></div></div></section>
<section class="section light" id="faq"><div class="wrap faq-layout"><div class="faq-intro"><p class="eyebrow">{T('Gut zu wissen','Good to know')}</p><h2>{T('Noch eine Frage?','One more question?')}</h2><p>{T('Hier findest du Antworten vor dem Kauf. Für alles Weitere erreichst du mich direkt.','Find answers before you buy. For anything else, you can reach me directly.')}</p><a class="text-link" href="{support}#contact" data-contact="support">{T('Robert kontaktieren','Contact Robert')}{icon('arrow')}</a></div><div>{faq_html}</div></div></section></main>'''
    (ROOT/home).write_text(shell(main,T('Apple-Health-Daten exportieren: CSV, JSON & Markdown | Strata','Export Apple Health Data: CSV, JSON & Markdown | Strata'),T('Deine Apple-Health-Daten als CSV, JSON oder Markdown. Für Excel, eigene Auswertungen und lokale KI. Strata für iPhone & iPad: einmalig 9,99 €.','Export Apple Health data to CSV, JSON or Markdown. For spreadsheets, your own analysis and local AI. Strata for iPhone & iPad: a $9.99 one-time purchase.')))
    address=f'Robert Meyer<br>Robert Meyer c/o Online-Impressum.de #4759<br>Europaring 90<br>53757 Sankt Augustin<br>{T("Deutschland","Germany")}'
    contact_link='<a href="https://mein.online-impressum.de/robert-meyer/" target="_blank" rel="noopener noreferrer">mein.online-impressum.de/robert-meyer</a>'
    support_sections=f'''<section id="contact"><h2>{T('Kontakt & Hilfe','Contact & help')}</h2><p>{T('Bei Fragen zur App, technischen Problemen oder Rückmeldungen erreichst du den Entwickler Robert Meyer direkt.','For questions about the app, technical problems or feedback, contact the developer Robert Meyer directly.')}</p><p>E-Mail: <a href="mailto:rm@kostenmanager.net">rm@kostenmanager.net</a><br>{T('Externes Kontaktformular','External contact form')}: {contact_link}</p><p>{T('Bei technischen Problemen beschreibe bitte kurz, was passiert, und nenne deine App-Version sowie die iOS-/iPadOS-Version. Bitte sende keine Gesundheitsdaten mit.','For technical problems, briefly describe what happens and include your app version and iOS/iPadOS version. Please do not include health data.')}</p><a class="btn" href="mailto:rm@kostenmanager.net" data-contact="support">{T('Nachricht schreiben','Write a message')}{icon('arrow')}</a><h3>{T('Produkt-Updates','Product updates')}</h3><p>{T('Wenn du per E-Mail über Strata informiert werden möchtest, kannst du dich über das Formular für Produkt-Updates anmelden. Die Anmeldung ist freiwillig. Du kannst deine Einwilligung jederzeit per E-Mail an rm@kostenmanager.net widerrufen.','If you would like to hear about Strata by email, you can sign up for product updates using the form. Signing up is optional. You can withdraw consent at any time by emailing rm@kostenmanager.net.')}</p><a href="mailto:rm@kostenmanager.net?subject=Strata%20Updates" data-contact="updates">{T('Für Produkt-Updates anmelden','Sign up for product updates')} ↗</a></section>
<section id="help"><h2>{T('Häufige Fragen','Frequently asked questions')}</h2>{faq_html}<h3>{T('Berechtigungen und leere Kategorien','Permissions and empty categories')}</h3><p>{T('Wenn Daten fehlen, prüfe zunächst, ob sie in Apple Health vorhanden sind und ob Strata die passenden Leserechte erhalten hat. Die verfügbaren Kategorien richten sich nach dem Datenbestand auf deinem Gerät.','If data are missing, first check whether the records exist in Apple Health and whether Strata has the relevant read permissions. Available categories depend on the data on your device.')}</p><h3>{T('Wichtige Hinweise','Important notes')}</h3><ul><li>{T('Die App stellt Daten bereit und strukturiert sie für den Export. Sie ersetzt keine medizinische, rechtliche oder datenschutzrechtliche Beratung.','The app provides data and structures it for export. It does not replace medical, legal or privacy advice.')}</li><li>{T('Strata liefert keine Diagnose, Therapieempfehlung oder medizinische Bewertung.','Strata provides no diagnosis, treatment recommendation or medical interpretation.')}</li><li>{T('Prüfe Gesundheitsdaten vor einer Weitergabe bewusst. Für selbst gewählte externe Analyse- und Cloud-Dienste gelten deren Datenschutzbedingungen.','Review health data carefully before sharing. External analysis and cloud services you choose are subject to their own privacy terms.')}</li></ul></section>
<section id="app-privacy"><h2>{T('App-Datenschutz','App privacy')}</h2><p>{T('Strata ist eine lokale App für iPhone und iPad. Der Zugriff auf Apple-Health-Daten und die Erstellung von Exportdateien erfolgen auf deinem Gerät.','Strata is a local app for iPhone and iPad. Access to Apple Health data and creation of export files happen on your device.')}</p><ul><li>{T('Die App liest Health-Daten nach deiner Freigabe. Sie verändert die Originaldaten nicht.','The app reads Health data after you grant permission. It does not modify the original records.')}</li><li>{T('Für Zugriff und Export gibt es keine Cloud-Pflicht.','There is no mandatory cloud processing for access or export.')}</li><li>{T('Die App verwendet kein Tracking, keine Werbung und keine Nutzerprofile.','The app uses no tracking, advertising or user profiles.')}</li><li>{T('Es gibt keine Registrierung, kein Nutzerkonto und kein Abo für den beschriebenen Ablauf.','There is no registration, account or subscription for the workflow described.')}</li><li>{T('Exportdateien werden nur auf ausdrückliche Nutzeraktion erstellt.','Export files are created only on explicit user action.')}</li><li>{T('Du bestimmst selbst, ob und wohin du Dateien weitergibst.','You decide whether and where to share your files.')}</li></ul><p>{T('Die Website greift nicht auf Apple Health zu. Ihre Exportvorschau verwendet ausschließlich fiktive Beispieldaten. Die folgenden Hinweise betreffen den Besuch der Website und die Kontaktaufnahme.','The website does not access Apple Health. Its export preview uses fictional sample data only. The following information concerns website visits and contact requests.')}</p></section>
<section id="website-privacy"><h2>{T('Datenschutz dieser Website','Website privacy')}</h2><h3>{T('1. Verantwortlicher','1. Data controller')}</h3><p>{address}<br>E-Mail: <a href="mailto:rm@kostenmanager.net">rm@kostenmanager.net</a></p><h3>{T('2. Aufruf der Website','2. Visiting the website')}</h3><p>{T('Beim Aufruf werden technisch erforderliche Verbindungsdaten wie die IP-Adresse, die angeforderte Adresse und Browserinformationen an den Webserver übermittelt, damit die Seite ausgeliefert werden kann. Die Bereitstellung und Sicherheit der Website beruhen auf dem berechtigten Interesse gemäß Art. 6 Abs. 1 lit. f DSGVO.','When you visit, connection data such as your IP address, requested address and browser information are transmitted to the web server so the page can be delivered. Providing and securing the website is based on legitimate interests under Article 6(1)(f) GDPR.')}</p><p>{T('Schriften werden über die Systemschrift deines Geräts dargestellt. Es werden keine Google Fonts, externen Videoplayer oder externen QR-Code-Dienste geladen. Bilder und QR-Codes werden mit der Website ausgeliefert.','Fonts use your device’s system typeface. No Google Fonts, external video players or external QR code services are loaded. Images and QR codes are served with the website.')}</p><h3>{T('3. Cookies und lokale Einstellungen','3. Cookies and local preferences')}</h3><p>{T('Diese Website setzt keine Cookies und führt keine Nutzerkonten. Deine Entscheidung zur optionalen Statistik wird unter „strata-privacy-v2“ im lokalen Speicher deines Browsers gespeichert. Sie bleibt dort, bis du sie änderst oder die Website-Daten im Browser löschst. Die Speicherung dient der Umsetzung deiner ausdrücklich gewählten Datenschutzeinstellung.','This website sets no cookies and creates no user accounts. Your optional analytics choice is stored as “strata-privacy-v2” in your browser’s local storage. It remains until you change it or clear the website’s data in your browser. This storage implements the privacy preference you explicitly select.')}</p><button type="button" class="privacy-settings" data-privacy-settings>{T('Datenschutzeinstellungen ändern','Change privacy settings')}</button><h3>{T('4. Optionale Reichweitenmessung mit Umami','4. Optional Umami analytics')}</h3><p>{T('Nur nach deiner Zustimmung wird Umami von cv.rm-on.de geladen. Damit werden Seitenaufrufe und ausgewählte Interaktionen erfasst, etwa App-Store-Klicks oder die Nutzung der Exportvorschau. Es werden keine Formularinhalte oder Gesundheitsdaten als Ereignisdaten an Umami übergeben. Beim Verbindungsaufbau werden technisch Verbindungsdaten an den Statistikserver übermittelt.','Only after your consent, Umami is loaded from cv.rm-on.de. It records page views and selected interactions, such as App Store clicks or use of the export preview. Form contents and health data are not sent to Umami as event data. Connecting to the analytics server necessarily transmits connection data.')}</p><p>{T('Rechtsgrundlage ist deine Einwilligung gemäß Art. 6 Abs. 1 lit. a DSGVO. Du kannst sie jederzeit über die Datenschutzeinstellungen widerrufen. Beim Widerruf wird die Seite neu geladen, damit das zuvor geladene Statistikskript nicht weiterläuft. Die Rechtmäßigkeit der Verarbeitung bis zum Widerruf bleibt unberührt.','The legal basis is your consent under Article 6(1)(a) GDPR. You can withdraw it at any time through privacy settings. On withdrawal, the page reloads to stop the previously loaded analytics script. Withdrawal does not affect the lawfulness of prior processing.')}</p><h3>{T('5. Kontaktformular und E-Mail','5. Contact form and email')}</h3><p>{T('Wenn du eine Anfrage sendest, verarbeiten wir deine E-Mail-Adresse, deinen optionalen Namen, die Nachricht sowie Angaben zur Quelle und Sprache der Anfrage. Das Formular übermittelt diese Angaben per HTTPS an den bestehenden n8n-Webhook auf n8n.top-beraternetzwerk.de zur Bearbeitung durch Robert Meyer. Das externe Kontaktformular auf mein.online-impressum.de unterliegt zusätzlich den Datenschutzinformationen dieses Anbieters.','When you send a request, we process your email address, optional name, message and information about its source and language. The form transmits these details via HTTPS to the existing n8n webhook at n8n.top-beraternetzwerk.de for Robert Meyer to handle. The external contact form at mein.online-impressum.de is also subject to that provider’s privacy information.')}</p><p>{T('Die Angaben werden zur Bearbeitung deiner Anfrage verwendet. Rechtsgrundlage ist Art. 6 Abs. 1 lit. b DSGVO bei vertragsbezogenen Anfragen oder Art. 6 Abs. 1 lit. f DSGVO für die Beantwortung sonstiger Anliegen. Sie werden gelöscht, wenn sie dafür nicht mehr erforderlich sind und keine gesetzlichen Aufbewahrungspflichten entgegenstehen. Bitte übermittle keine Gesundheitsdaten über diese Kontaktwege.','Details are used to handle your request. The legal basis is Article 6(1)(b) GDPR for contract-related enquiries or Article 6(1)(f) GDPR for responding to other requests. They are deleted when no longer needed for that purpose, unless statutory retention obligations apply. Please do not send health data through these contact channels.')}</p><h3>{T('6. Produkt-Updates / Newsletter','6. Product updates / newsletter')}</h3><p>{T('Bei einer freiwilligen Anmeldung werden deine E-Mail-Adresse, dein optionaler Name und deine Einwilligung über denselben Webhook für Produkt-Updates zu Strata übermittelt. Rechtsgrundlage ist Art. 6 Abs. 1 lit. a DSGVO. Du kannst deine Einwilligung jederzeit mit Wirkung für die Zukunft per E-Mail an rm@kostenmanager.net widerrufen. Nach einem Widerruf wird deine Adresse nicht mehr für den Versand verwendet; erforderliche Nachweise und gesetzliche Aufbewahrungspflichten bleiben davon unberührt.','If you voluntarily sign up, your email address, optional name and consent are transmitted through the same webhook for Strata product updates. The legal basis is Article 6(1)(a) GDPR. You can withdraw consent for the future at any time by emailing rm@kostenmanager.net. After withdrawal your address will no longer be used for sending updates; necessary records and statutory retention obligations remain unaffected.')}</p><h3>{T('7. Externe Links und App Store','7. External links and the App Store')}</h3><p>{T('Links zum Apple App Store und zu externen Kontaktangeboten öffnen die jeweiligen Dienste. Erst beim Aufrufen gelten deren Datenverarbeitungs- und Datenschutzbedingungen. Der Kauf der App erfolgt im Apple App Store.','Links to the Apple App Store and external contact services open those services. Their processing and privacy terms apply when you visit them. The app purchase takes place in the Apple App Store.')}</p><h3>{T('8. Deine Rechte','8. Your rights')}</h3><p>{T('Du hast im Rahmen der gesetzlichen Voraussetzungen Rechte auf Auskunft, Berichtigung, Löschung, Einschränkung der Verarbeitung und Datenübertragbarkeit. Bei Verarbeitungen auf Basis berechtigter Interessen kannst du aus Gründen deiner besonderen Situation widersprechen. Einwilligungen kannst du jederzeit für die Zukunft widerrufen. Außerdem kannst du dich bei einer Datenschutzaufsichtsbehörde beschweren. Für Anliegen zu deinen Daten erreichst du Robert Meyer unter rm@kostenmanager.net.','Subject to the statutory conditions, you have rights to access, rectification, erasure, restriction of processing and data portability. For processing based on legitimate interests, you may object on grounds relating to your particular situation. You may withdraw consent at any time for the future. You may also lodge a complaint with a data protection supervisory authority. Contact Robert Meyer at rm@kostenmanager.net with requests concerning your data.')}</p><p class="legal-date">{T('Stand: 5. September 2026','Last updated: September 5, 2026')}</p></section>
<section id="imprint"><h2>{T('Impressum','Legal notice')}</h2><h3>{T('Angaben gemäß § 5 DDG','Information under Section 5 DDG')}</h3><p>{address}</p><h3>{T('Kontakt','Contact')}</h3><p>E-Mail: <a href="mailto:rm@kostenmanager.net">rm@kostenmanager.net</a><br>{T('Kontaktformular','Contact form')}: {contact_link}</p><h3>{T('Verantwortlich für die Inhalte','Responsible for content')}</h3><p>{address}</p><h3>{T('Verbraucherstreitbeilegung','Consumer dispute resolution')}</h3><p>{T('Ich bin nicht bereit oder verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.','I am not willing or obliged to participate in dispute resolution proceedings before a consumer arbitration board.')}</p></section>'''
    toc=''.join(f'<a href="#{a}">{t}</a>' for a,t in [('contact',T('Kontakt & Hilfe','Contact & help')),('help','FAQ'),('app-privacy',T('App-Datenschutz','App privacy')),('website-privacy',T('Website-Datenschutz','Website privacy')),('imprint',T('Impressum','Legal notice'))])
    support_main=f'''<main id="main"><section class="support-hero"><div class="wrap"><p class="eyebrow accent">Strata Support</p><h1>{T('Wir sind erreichbar.','We’re here to help.')}</h1><p>{T('Antworten, Kontakt und alles zum Datenschutz. Direkt vom Entwickler deiner App.','Answers, contact details and privacy information. Directly from your app’s developer.')}</p><nav class="support-links" aria-label="{T('Support-Bereiche','Support sections')}">{toc}</nav></div></section><div class="section light"><div class="wrap support-content"><nav class="support-toc" aria-label="{T('Inhaltsverzeichnis','Contents')}">{toc}</nav><div class="support-copy">{support_sections}</div></div></div></main>'''
    (ROOT/support).write_text(shell(support_main,T('Strata Support · Kontakt, Datenschutz und Impressum','Strata Support · Contact, privacy and legal notice'),T('Hilfe zur Strata App, Kontakt zu Robert Meyer, häufige Fragen, App-Datenschutz, Website-Datenschutz und Impressum.','Help with Strata, contact Robert Meyer, frequently asked questions, app privacy, website privacy and legal information.'),True))
write_discovery(ROOT)
print('Built four localized HTML pages, sitemap.xml and robots.txt')
